'use client';

import { Flame } from 'lucide-react';
import type { KeyboardEvent, MouseEvent } from 'react';
import { useEffect, useState, useRef } from 'react';
import { useReducedMotion } from '../../../hooks/use-reduced-motion';
import { cn } from '../../../lib/utils';

/**
 * POS health status for color mapping
 * Note: 'healthy' maps to POSStatus 'active' from backend
 */
export type POSStatus = 'healthy' | 'warning' | 'critical';

/**
 * Map backend POSStatus ('active') to marker status ('healthy')
 */
export type BackendPOSStatus = 'active' | 'warning' | 'critical';

export const mapBackendStatus = (status: BackendPOSStatus): POSStatus => {
  if (status === 'active') return 'healthy';
  return status;
};

/**
 * Marker size variants
 */
export type MarkerSize = 'sm' | 'md' | 'lg' | 'xl';
/**
 * Component props
 */
export interface AnimatedPOSMarkerProps {
  /** Health status determining color scheme */
  status: POSStatus;
  /** Marker size variant */
  size?: MarkerSize;
  /** Optional count for cluster markers (displays in center) */
  count?: number;
  /** Optional click handler */
  onClick?: (e: MouseEvent<HTMLDivElement>) => void;
  /** Additional CSS classes */
  className?: string;
  /** Enable FPS monitoring (dev only) - defaults to false */
  enableFpsMonitor?: boolean;
}

/**
 * Color configuration for each status
 */
const STATUS_COLORS = {
  healthy: {
    inner: 'bg-emerald-500', // #10b981
    outer: 'bg-emerald-400', // #34d399
    glow: 'shadow-emerald-500/50',
    pulse: 'bg-emerald-400', // Removed /30 - opacity controlled by CSS animation
  },
  warning: {
    inner: 'bg-orange-500', // #f59e0b
    outer: 'bg-orange-400', // #fb923c
    glow: 'shadow-orange-500/50',
    pulse: 'bg-orange-400', // Removed /30 - opacity controlled by CSS animation
  },
  critical: {
    inner: 'bg-pink-500', // #ec4899
    outer: 'bg-red-500', // #ef4444
    glow: 'shadow-red-500/50',
    pulse: 'bg-red-400', // Removed /30 - opacity controlled by CSS animation
  },
} as const;

/**
 * Size configuration
 * Based on design spec from plan.md:
 * - sm: Single points (16px inner, 28px glow, 40px pulse)
 * - md: Small clusters <50 (24px inner, 40px glow, 56px pulse)
 * - lg: Med clusters 50-99 (32px inner, 52px glow, 72px pulse)
 * - xl: Large clusters 100+ (40px inner, 64px glow, 88px pulse)
 */
const SIZE_CONFIG = {
  sm: {
    inner: 'size-4', // 16px
    glow: 'size-7', // 28px
    pulse: 'size-10', // 40px
    icon: 'size-2.5', // 10px
    text: 'text-[8px]',
  },
  md: {
    inner: 'size-6', // 24px
    glow: 'size-10', // 40px
    pulse: 'size-14', // 56px
    icon: 'size-3.5', // 14px
    text: 'text-[10px]',
  },
  lg: {
    inner: 'size-8', // 32px
    glow: 'w-[52px] h-[52px]', // 52px (arbitrary value)
    pulse: 'w-[72px] h-[72px]', // 72px (arbitrary value)
    icon: 'size-4', // 16px
    text: 'text-xs',
  },
  xl: {
    inner: 'size-10', // 40px
    glow: 'size-16', // 64px
    pulse: 'w-[88px] h-[88px]', // 88px (arbitrary value)
    icon: 'size-5', // 20px
    text: 'text-sm',
  },
} as const;

interface MarkerContentProps {
  status: POSStatus;
  sizes: (typeof SIZE_CONFIG)[MarkerSize];
  count?: number;
  onClick?: (e: MouseEvent<HTMLDivElement>) => void;
  className?: string;
  shouldAnimate: boolean;
  isInViewport: boolean;
}

/**
 * Marker content for interactive variant
 */
function InteractiveMarker({
  status,
  sizes,
  count,
  onClick,
  className,
  shouldAnimate,
  isInViewport,
}: MarkerContentProps) {
  const colors = STATUS_COLORS[status];
  const [isHovered, setIsHovered] = useState(false);

  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if ((e.key === 'Enter' || e.key === ' ') && onClick) {
      e.preventDefault();
      onClick(e as unknown as MouseEvent<HTMLDivElement>);
    }
  };

  return (
    <div
      className={cn('relative inline-flex cursor-pointer items-center justify-center', className)}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      role="button"
      tabIndex={0}
      aria-label={count ? `${status} cluster with ${count} POS machines` : `${status} POS machine`}
      style={{
        // GPU optimization - only apply will-change on hover
        willChange: isHovered ? 'transform, opacity' : 'auto',
        transform: 'translateZ(0)', // Force GPU layer
        backfaceVisibility: 'hidden', // Prevent flicker
      }}
    >
      {/* Outer Pulse Ring (animated only when in viewport) */}
      <div
        className={cn(
          sizes.pulse,
          colors.pulse,
          'absolute rounded-full',
          shouldAnimate && isInViewport ? 'animate-marker-pulse' : 'opacity-0'
        )}
        aria-hidden="true"
      />

      {/* Middle Glow Ring */}
      <div
        className={cn(
          sizes.glow,
          colors.outer,
          'absolute rounded-full opacity-60 blur-sm',
          colors.glow,
          // Enhanced shadow: dark shadow + white ring + glow
          'shadow-[0_2px_8px_rgba(0,0,0,0.3),0_0_0_2px_rgba(255,255,255,0.2),0_0_20px_var(--glow-color)]'
        )}
        style={
          {
            '--glow-color': getGlowColor(status),
          } as React.CSSProperties
        }
        aria-hidden="true"
      />

      {/* Inner Circle (core marker) */}
      <div
        className={cn(
          sizes.inner,
          colors.inner,
          'relative z-10 flex items-center justify-center rounded-full',
          'shadow-md transition-all duration-150 ease-out',
          'hover:z-20 hover:scale-110',
          'active:scale-95'
        )}
      >
        {/* Icon or Count */}
        {count !== undefined && count > 0 ? (
          <span className={cn('font-bold text-white', sizes.text)}>{count}</span>
        ) : (
          <Flame className={cn(sizes.icon, 'text-white')} aria-hidden="true" />
        )}
      </div>
    </div>
  );
}

/**
 * Get CSS color value for glow effect
 */
function getGlowColor(status: POSStatus): string {
  const colors = {
    healthy: 'rgba(16, 185, 129, 0.5)', // emerald-500
    warning: 'rgba(245, 158, 11, 0.5)', // orange-500
    critical: 'rgba(239, 68, 68, 0.5)', // red-500
  };
  return colors[status];
}

/**
 * Marker content for static variant
 */
function StaticMarker({
  status,
  sizes,
  count,
  className,
  shouldAnimate,
  isInViewport,
}: Omit<MarkerContentProps, 'onClick'>) {
  const colors = STATUS_COLORS[status];

  return (
    <div
      className={cn('relative inline-flex items-center justify-center', className)}
      style={{
        transform: 'translateZ(0)', // Force GPU layer
        backfaceVisibility: 'hidden', // Prevent flicker
      }}
    >
      {/* Outer Pulse Ring (animated only when in viewport) */}
      <div
        className={cn(
          sizes.pulse,
          colors.pulse,
          'absolute rounded-full',
          shouldAnimate && isInViewport ? 'animate-marker-pulse' : 'opacity-0'
        )}
        aria-hidden="true"
      />

      {/* Middle Glow Ring */}
      <div
        className={cn(
          sizes.glow,
          colors.outer,
          'absolute rounded-full opacity-60 blur-sm',
          colors.glow,
          // Enhanced shadow: dark shadow + white ring + glow
          'shadow-[0_2px_8px_rgba(0,0,0,0.3),0_0_0_2px_rgba(255,255,255,0.2),0_0_20px_var(--glow-color)]'
        )}
        style={
          {
            '--glow-color': getGlowColor(status),
          } as React.CSSProperties
        }
        aria-hidden="true"
      />

      {/* Inner Circle (core marker) */}
      <div
        className={cn(
          sizes.inner,
          colors.inner,
          'relative z-10 flex items-center justify-center rounded-full',
          'shadow-md'
        )}
      >
        {/* Icon or Count */}
        {count !== undefined && count > 0 ? (
          <span className={cn('font-bold text-white', sizes.text)}>{count}</span>
        ) : (
          <Flame className={cn(sizes.icon, 'text-white')} aria-hidden="true" />
        )}
      </div>
    </div>
  );
}

/**
 * AnimatedPOSMarker Component
 */
export function AnimatedPOSMarker({
  status,
  size = 'md',
  count,
  onClick,
  className,
  enableFpsMonitor = false,
}: AnimatedPOSMarkerProps) {
  const sizes = SIZE_CONFIG[size];
  const prefersReducedMotion = useReducedMotion();
  const [animationReady, setAnimationReady] = useState(false);
  const [isInViewport, setIsInViewport] = useState(true); // Default true for initial render
  const markerRef = useRef<HTMLDivElement>(null);

  // Lazy animation initialization - prevent initial render jank
  useEffect(() => {
    const timer = setTimeout(() => {
      setAnimationReady(true);
    }, 100);

    return () => clearTimeout(timer);
  }, []);

  // Viewport detection with IntersectionObserver
  useEffect(() => {
    if (!markerRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          setIsInViewport(entry.isIntersecting);
        });
      },
      {
        threshold: 0,
        rootMargin: '50px', // Start animating slightly before entering viewport
      }
    );

    observer.observe(markerRef.current);

    return () => {
      observer.disconnect();
    };
  }, []);

  // FPS monitoring (dev only)
  useEffect(() => {
    if (!enableFpsMonitor || process.env.NODE_ENV === 'production') return;

    let frameCount = 0;
    let lastTime = performance.now();
    let animationFrameId: number;

    const measureFPS = () => {
      frameCount++;
      const currentTime = performance.now();

      if (currentTime >= lastTime + 1000) {
        const fps = Math.round((frameCount * 1000) / (currentTime - lastTime));
        console.log(`[AnimatedPOSMarker FPS]: ${fps}`);
        frameCount = 0;
        lastTime = currentTime;
      }

      animationFrameId = requestAnimationFrame(measureFPS);
    };

    animationFrameId = requestAnimationFrame(measureFPS);

    return () => {
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
      }
    };
  }, [enableFpsMonitor]);

  // Determine if animations should run
  const shouldAnimate = !prefersReducedMotion && animationReady;

  if (onClick) {
    return (
      <div ref={markerRef}>
        <InteractiveMarker
          status={status}
          sizes={sizes}
          count={count}
          onClick={onClick}
          className={className}
          shouldAnimate={shouldAnimate}
          isInViewport={isInViewport}
        />
      </div>
    );
  }

  return (
    <div ref={markerRef}>
      <StaticMarker
        status={status}
        sizes={sizes}
        count={count}
        className={className}
        shouldAnimate={shouldAnimate}
        isInViewport={isInViewport}
      />
    </div>
  );
}

export * from './map';
export * from './map-cluster-layer';
export * from './animated-pos-marker';

'use client';

import { useEffect, useId, useState, useMemo, useRef } from 'react';
import type MapLibreGL from 'maplibre-gl';
import { useMap, MapMarker, MarkerContent } from './map';
import { AnimatedPOSMarker, mapBackendStatus } from './animated-pos-marker';

/**
 * Props for MapClusterLayer component
 * @template T - Type of properties attached to GeoJSON features
 */
export interface MapClusterLayerProps<T = Record<string, unknown>> {
  /**
   * GeoJSON data source
   * Can be either a URL string or a FeatureCollection object
   */
  data: string | GeoJSON.FeatureCollection<GeoJSON.Point, T>;

  /**
   * Cluster radius in pixels
   * Points within this radius will be grouped into a cluster
   * @default 50
   */
  clusterRadius?: number;

  /**
   * Maximum zoom level for clustering
   * Beyond this zoom, individual points are always shown
   * @default 14
   */
  clusterMaxZoom?: number;

  /**
   * Colors for clusters (3-tier array)
   * [small clusters, medium clusters, large clusters]
   * Interpolated based on point count
   * @default ['#10b981', '#f59e0b', '#ec4899'] (green, orange, pink)
   */
  clusterColors?: [string, string, string];

  /**
   * Color for individual unclustered points
   * @default '#3b82f6' (blue)
   */
  pointColor?: string;

  /**
   * NEW: Extract status from point properties for coloring
   * @param properties - Point properties
   * @returns POSStatus for color mapping
   */
  getPointStatus?: (properties: T) => 'active' | 'warning' | 'critical';

  /**
   * NEW: Use animated DOM markers for unclustered points
   * Performance note: Only enable for <500 points
   * @default false
   */
  animatedPoints?: boolean;

  /**
   * NEW: Show glow effect on clusters
   * @default true
   */
  clusterGlow?: boolean;

  /**
   * Click handler for cluster markers
   * Receives cluster ID, coordinates, point count, and all properties in the cluster
   */
  onClusterClick?: (
    clusterId: number,
    coordinates: [number, number],
    pointCount: number,
    properties: T[]
  ) => void;

  /**
   * Click handler for individual point markers
   * Receives the full GeoJSON feature and coordinates
   */
  onPointClick?: (
    feature: GeoJSON.Feature<GeoJSON.Point, T>,
    coordinates: [number, number]
  ) => void;
}

/**
 * MapClusterLayer Component
 * Renders clustered markers on a MapLibre GL map
 */
export function MapClusterLayer<T = Record<string, unknown>>({
  data,
  clusterRadius = 50,
  clusterMaxZoom = 14,
  clusterColors = ['#10b981', '#f59e0b', '#ec4899'],
  pointColor = '#3b82f6',
  getPointStatus,
  animatedPoints = false,
  clusterGlow = false,
  onClusterClick,
  onPointClick,
}: MapClusterLayerProps<T>) {
  const { map, isLoaded } = useMap();
  const sourceId = useId();
  const clusterLayerId = `${sourceId}-clusters`;
  const clusterGlowLayerId = `${sourceId}-cluster-glow`;
  const clusterPulseLayerId = `${sourceId}-cluster-pulse`;
  const clusterCountLayerId = `${sourceId}-cluster-count`;
  const pointLayerId = `${sourceId}-points`;
  const [unclusteredPoints, setUnclusteredPoints] = useState<GeoJSON.Feature<GeoJSON.Point, T>[]>(
    []
  );

  // Phase 2 Task 2.1: Add transition state management
  const [isTransitioning, setIsTransitioning] = useState(false);
  const transitionTimeoutRef = useRef<number | null>(null);

  // Phase 1 Task 2.2: Add requestAnimationFrame debouncing ref
  const updatePointsRef = useRef<number | null>(null);

  useEffect(() => {
    if (!map || !isLoaded) return;

    // Add GeoJSON source with clustering enabled
    map.addSource(sourceId, {
      type: 'geojson',
      data: data as string | GeoJSON.FeatureCollection,
      cluster: true,
      clusterRadius,
      clusterMaxZoom,
    });

    // Add pulse layer (outermost layer with animation) if enabled
    if (clusterGlow) {
      map.addLayer({
        id: clusterPulseLayerId,
        type: 'circle',
        source: sourceId,
        filter: ['has', 'point_count'],
        paint: {
          // Same color as main cluster
          'circle-color': [
            'step',
            ['get', 'point_count'],
            clusterColors[0], // Green for small clusters (< 50 points)
            50,
            clusterColors[1], // Orange for medium clusters (50-99 points)
            100,
            clusterColors[2], // Pink/Red for large clusters (100+ points)
          ],
          // 2x main radius for pulse effect
          'circle-radius': [
            'step',
            ['get', 'point_count'],
            40, // 40px pulse for small clusters (2x main 20px)
            50,
            60, // 60px pulse for medium clusters (2x main 30px)
            100,
            80, // 80px pulse for large clusters (2x main 40px)
          ],
          'circle-opacity': 0.0, // Will be animated
        },
      });
    }

    // Add glow layer (rendered behind main cluster layer) if enabled
    if (clusterGlow) {
      map.addLayer({
        id: clusterGlowLayerId,
        type: 'circle',
        source: sourceId,
        filter: ['has', 'point_count'],
        paint: {
          // Same color as main cluster
          'circle-color': [
            'step',
            ['get', 'point_count'],
            clusterColors[0], // Green for small clusters (< 50 points)
            50,
            clusterColors[1], // Orange for medium clusters (50-99 points)
            100,
            clusterColors[2], // Pink/Red for large clusters (100+ points)
          ],
          // 1.5x main radius for glow effect
          'circle-radius': [
            'step',
            ['get', 'point_count'],
            30, // 30px glow for small clusters
            50,
            45, // 45px glow for medium clusters
            100,
            60, // 60px glow for large clusters
          ],
          'circle-blur': 1, // Gaussian blur for glow
          'circle-opacity': 0.4, // Semi-transparent
        },
      });
    }

    // Add cluster layer (circles with size/color based on point count)
    map.addLayer({
      id: clusterLayerId,
      type: 'circle',
      source: sourceId,
      filter: ['has', 'point_count'],
      paint: {
        // Color interpolation based on point count
        'circle-color': [
          'step',
          ['get', 'point_count'],
          clusterColors[0], // Green for small clusters (< 50 points)
          50,
          clusterColors[1], // Orange for medium clusters (50-99 points)
          100,
          clusterColors[2], // Pink/Red for large clusters (100+ points)
        ],
        // Radius interpolation based on point count
        'circle-radius': [
          'step',
          ['get', 'point_count'],
          20, // 20px for small clusters (< 50 points)
          50,
          30, // 30px for medium clusters (50-99 points)
          100,
          40, // 40px for large clusters (100+ points)
        ],
      },
    });

    // Add cluster count label layer
    // CRITICAL: Symbol layers must be added LAST to render on top of all other layers
    // This ensures cluster numbers appear above animated DOM markers when animatedPoints=true
    map.addLayer({
      id: clusterCountLayerId,
      type: 'symbol',
      source: sourceId,
      filter: ['has', 'point_count'],
      layout: {
        'text-field': '{point_count_abbreviated}',
        'text-font': ['Open Sans Semibold', 'Arial Unicode MS Bold'],
        'text-size': 14, // Increased from 12 for better visibility
        'text-allow-overlap': true, // Force labels to render even if they overlap
        'text-ignore-placement': true, // Ignore placement constraints
      },
      paint: {
        'text-color': '#ffffff',
        'text-halo-color': 'rgba(0, 0, 0, 0.3)', // Add subtle halo for contrast
        'text-halo-width': 1,
      },
    });

    // Add unclustered points layer (only if not using animated DOM markers)
    if (!animatedPoints) {
      map.addLayer({
        id: pointLayerId,
        type: 'circle',
        source: sourceId,
        filter: ['!', ['has', 'point_count']],
        paint: {
          'circle-color': pointColor,
          'circle-radius': 8,
          'circle-stroke-width': 2,
          'circle-stroke-color': '#ffffff',
        },
      });
    }

    // Click handler for clusters
    const handleClusterClick = (e: MapLibreGL.MapMouseEvent) => {
      const features = map.queryRenderedFeatures(e.point, {
        layers: [clusterLayerId],
      });

      if (features.length > 0 && onClusterClick) {
        const feature = features[0];
        if (!feature) return;

        const clusterId = feature.properties?.cluster_id as number;
        const coordinates = (feature.geometry as GeoJSON.Point).coordinates as [number, number];
        const pointCount = feature.properties?.point_count as number;

        // Get all leaves (individual points) in the cluster
        const source = map.getSource(sourceId) as MapLibreGL.GeoJSONSource;
        source
          .getClusterLeaves(clusterId, pointCount, 0)
          .then((leaves: GeoJSON.Feature[]) => {
            if (leaves) {
              const properties = leaves.map((f) => f.properties as T);
              onClusterClick(clusterId, coordinates, pointCount, properties);
            }
          })
          .catch((err: Error) => {
            console.error('Error getting cluster leaves:', err);
          });
      }
    };

    // Click handler for individual points (only if not using animated points)
    const handlePointClick = !animatedPoints
      ? (e: MapLibreGL.MapMouseEvent) => {
          const features = map.queryRenderedFeatures(e.point, {
            layers: [pointLayerId],
          });

          if (features.length > 0 && onPointClick) {
            const rawFeature = features[0];
            if (!rawFeature) return;

            // Convert MapGeoJSONFeature to GeoJSON.Feature with proper typing
            const feature: GeoJSON.Feature<GeoJSON.Point, T> = {
              type: 'Feature',
              geometry: rawFeature.geometry as GeoJSON.Point,
              properties: rawFeature.properties as T,
            };
            const coordinates = feature.geometry.coordinates.slice() as [number, number];
            onPointClick(feature, coordinates);
          }
        }
      : () => {}; // No-op if using animated points (they have own click handlers)

    // Register click handlers
    map.on('click', clusterLayerId, handleClusterClick);
    if (!animatedPoints) {
      map.on('click', pointLayerId, handlePointClick);
    }

    // Change cursor on hover
    const handleClusterMouseEnter = () => {
      map.getCanvas().style.cursor = 'pointer';
    };
    const handleClusterMouseLeave = () => {
      map.getCanvas().style.cursor = '';
    };
    const handlePointMouseEnter = () => {
      map.getCanvas().style.cursor = 'pointer';
    };
    const handlePointMouseLeave = () => {
      map.getCanvas().style.cursor = '';
    };

    map.on('mouseenter', clusterLayerId, handleClusterMouseEnter);
    map.on('mouseleave', clusterLayerId, handleClusterMouseLeave);
    if (!animatedPoints) {
      map.on('mouseenter', pointLayerId, handlePointMouseEnter);
      map.on('mouseleave', pointLayerId, handlePointMouseLeave);
    }

    // Animate pulse layer (if enabled)
    let animationFrameId: number | null = null;
    if (clusterGlow) {
      const animatePulse = () => {
        // Phase 2 Task 2.2: Pause animation during transitions
        if (isTransitioning) {
          animationFrameId = requestAnimationFrame(animatePulse);
          return;
        }

        const timestamp = performance.now();
        // 2.5s cycle (matching CSS animation duration)
        const progress = (timestamp % 2500) / 2500;

        // Opacity: 0.3 → 0 → 0.3 (pulse effect)
        const opacity =
          progress < 0.5
            ? 0.3 * (1 - progress * 2) // Fade out (0.3 → 0)
            : 0.3 * ((progress - 0.5) * 2); // Fade in (0 → 0.3)

        // Scale: 1 → 2 → 1 (radius expansion)
        const scale = 1 + progress;

        try {
          if (map.getLayer?.(clusterPulseLayerId)) {
            map.setPaintProperty(clusterPulseLayerId, 'circle-opacity', opacity);
            map.setPaintProperty(clusterPulseLayerId, 'circle-radius', [
              'step',
              ['get', 'point_count'],
              20 * scale, // Small clusters
              50,
              30 * scale, // Medium clusters
              100,
              40 * scale, // Large clusters
            ]);
          }
        } catch (_error) {
          // Ignore errors during animation (layer might be removed)
        }

        animationFrameId = requestAnimationFrame(animatePulse);
      };

      animationFrameId = requestAnimationFrame(animatePulse);
    }

    // Cleanup on unmount
    return () => {
      if (!map) return;

      // Stop animation
      if (animationFrameId !== null) {
        cancelAnimationFrame(animationFrameId);
      }

      try {
        // Remove event listeners (safe even if handlers don't exist)
        map.off('click', clusterLayerId, handleClusterClick);
        if (!animatedPoints) {
          map.off('click', pointLayerId, handlePointClick);
          map.off('mouseenter', pointLayerId, handlePointMouseEnter);
          map.off('mouseleave', pointLayerId, handlePointMouseLeave);
        }
        map.off('mouseenter', clusterLayerId, handleClusterMouseEnter);
        map.off('mouseleave', clusterLayerId, handleClusterMouseLeave);

        // Remove layers only if they exist
        if (map.getLayer?.(clusterLayerId)) {
          map.removeLayer(clusterLayerId);
        }
        if (map.getLayer?.(clusterGlowLayerId)) {
          map.removeLayer(clusterGlowLayerId);
        }
        if (map.getLayer?.(clusterPulseLayerId)) {
          map.removeLayer(clusterPulseLayerId);
        }
        if (map.getLayer?.(clusterCountLayerId)) {
          map.removeLayer(clusterCountLayerId);
        }
        if (!animatedPoints && map.getLayer && map.getLayer(pointLayerId)) {
          map.removeLayer(pointLayerId);
        }

        // Remove source only if it exists
        if (map.getSource?.(sourceId)) {
          map.removeSource(sourceId);
        }
      } catch (_error) {
        // Silently handle cleanup errors (map may have been destroyed)
        console.warn('MapClusterLayer cleanup error (non-critical):', _error);
      }
    };
  }, [
    map,
    isLoaded,
    data,
    clusterRadius,
    clusterMaxZoom,
    clusterColors,
    pointColor,
    animatedPoints,
    clusterGlow,
    // NOTE: isTransitioning intentionally NOT in deps to prevent layer recreation
    // Animation pause is handled inside animatePulse() closure
    onClusterClick,
    onPointClick,
    sourceId,
    clusterLayerId,
    clusterGlowLayerId,
    clusterPulseLayerId,
    clusterCountLayerId,
    pointLayerId,
  ]);

  // Phase 2 Task 2.3: Dim glow effect during transitions
  useEffect(() => {
    if (!map || !isLoaded || !clusterGlow) return;

    try {
      if (map.getLayer?.(clusterGlowLayerId)) {
        // Dim glow during transitions to reduce visual noise
        const opacity = isTransitioning ? 0.2 : 0.4;
        map.setPaintProperty(clusterGlowLayerId, 'circle-opacity', opacity);
      }
    } catch (_error) {
      // Ignore errors if layer doesn't exist
    }
  }, [map, isLoaded, clusterGlow, isTransitioning, clusterGlowLayerId]);

  // Track unclustered points for animated DOM markers
  useEffect(() => {
    if (!map || !isLoaded || !animatedPoints) return;

    const updatePoints = () => {
      // Phase 2 Task 2.1: Signal transition start
      setIsTransitioning(true);

      // Clear existing transition timeout
      if (transitionTimeoutRef.current) {
        clearTimeout(transitionTimeoutRef.current);
      }

      // Cancel pending update
      if (updatePointsRef.current !== null) {
        cancelAnimationFrame(updatePointsRef.current);
      }

      // Phase 1 Task 2.2: Schedule update for next frame (sync with MapLibre render)
      updatePointsRef.current = requestAnimationFrame(() => {
        const source = map.getSource(sourceId) as MapLibreGL.GeoJSONSource;
        if (!source) return;

        // Phase 1 Task 2.1: Query source features for animatedPoints mode
        // In animatedPoints mode, we don't render GL point layer, so queryRenderedFeatures returns empty
        // Instead, query source and filter out clusters to get unclustered points
        const features = map.querySourceFeatures(sourceId, {
          sourceLayer: undefined,
          filter: ['!', ['has', 'point_count']], // Exclude clusters - only get unclustered points
        });

        // Phase 1 Task 2.4: Add viewport bounds checking
        const bounds = map.getBounds();
        const visibleFeatures = features.filter((f) => {
          const coords = (f.geometry as GeoJSON.Point).coordinates;
          return bounds.contains([coords[0]!, coords[1]!]);
        });

        // Convert MapGeoJSONFeature to GeoJSON.Feature
        const convertedFeatures: GeoJSON.Feature<GeoJSON.Point, T>[] = visibleFeatures.map((f) => ({
          type: 'Feature',
          geometry: f.geometry as GeoJSON.Point,
          properties: f.properties as T,
        }));

        setUnclusteredPoints(convertedFeatures);
        updatePointsRef.current = null;

        // Phase 2 Task 2.1: Signal transition end after React renders
        transitionTimeoutRef.current = window.setTimeout(() => {
          setIsTransitioning(false);
        }, 300); // Match typical animation duration
      });
    };

    // Task 2.3: Listen to both moveend and data events
    // 'data' event fires when clustering recalculation completes
    const handleDataEvent = (e: MapLibreGL.MapDataEvent) => {
      // Only update when source data changes (clustering recalc)
      // @ts-expect-error - MapLibre types incomplete for data event properties
      if (e.sourceId === sourceId && e.isSourceLoaded) {
        updatePoints();
      }
    };

    map.on('moveend', updatePoints);
    map.on('data', handleDataEvent);
    updatePoints();

    return () => {
      map.off('moveend', updatePoints);
      map.off('data', handleDataEvent);
      if (updatePointsRef.current !== null) {
        cancelAnimationFrame(updatePointsRef.current);
      }
      // Phase 2 Task 2.1: Clear transition timeout
      if (transitionTimeoutRef.current !== null) {
        clearTimeout(transitionTimeoutRef.current);
      }
    };
  }, [map, isLoaded, animatedPoints, sourceId]);

  // Memoize marker components to prevent unnecessary re-renders
  const markerComponents = useMemo(() => {
    if (!animatedPoints || unclusteredPoints.length === 0) return null;

    return unclusteredPoints.map((feature) => {
      const [lng, lat] = feature.geometry.coordinates;
      const status = getPointStatus?.(feature.properties as T) ?? 'active';
      const markerStatus = mapBackendStatus(status);
      const featureId = (feature.properties as { id?: string })?.id ?? `${lng}-${lat}`;

      return (
        <MapMarker
          key={featureId}
          longitude={lng!}
          latitude={lat!}
          onClick={(e) => {
            e.stopPropagation();
            onPointClick?.(feature, [lng!, lat!]);
          }}
        >
          <div
            style={{
              // Phase 2 Task 2.4: Fade markers during transitions
              opacity: isTransitioning ? 0.7 : 1,
              transition: 'opacity 200ms ease-in-out',
              // Ensure markers don't block cluster clicks during transition
              pointerEvents: isTransitioning ? 'none' : 'auto',
            }}
          >
            <MarkerContent>
              <AnimatedPOSMarker status={markerStatus} size="sm" />
            </MarkerContent>
          </div>
        </MapMarker>
      );
    });
  }, [animatedPoints, unclusteredPoints, getPointStatus, onPointClick, isTransitioning]);

  // Render DOM markers for unclustered points when animatedPoints is enabled
  if (markerComponents) {
    return <>{markerComponents}</>;
  }

  // Component renders via MapLibre layers (no DOM output)
  return null;
}

'use client';

import MapLibreGL, { type PopupOptions, type MarkerOptions } from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { useTheme } from 'next-themes';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { createPortal } from 'react-dom';
import { X, Minus, Plus, Locate, Maximize, Loader2 } from 'lucide-react';

import { cn } from '../../../lib/utils';

type MapContextValue = {
  map: MapLibreGL.Map | null;
  isLoaded: boolean;
};

const MapContext = createContext<MapContextValue | null>(null);

function useMap() {
  const context = useContext(MapContext);
  if (!context) {
    throw new Error('useMap must be used within a Map component');
  }
  return context;
}

const defaultStyles = {
  dark: 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',
  light: 'https://basemaps.cartocdn.com/gl/positron-gl-style/style.json',
};

type MapStyleOption = string | MapLibreGL.StyleSpecification;

type MapProps = {
  children?: ReactNode;
  /** Custom map styles for light and dark themes. Overrides the default Carto styles. */
  styles?: {
    light?: MapStyleOption;
    dark?: MapStyleOption;
  };
} & Omit<MapLibreGL.MapOptions, 'container' | 'style'>;

const DefaultLoader = () => (
  <div className="absolute inset-0 flex items-center justify-center">
    <div className="flex gap-1">
      <span className="size-1.5 animate-pulse rounded-full bg-muted-foreground/60" />
      <span className="size-1.5 animate-pulse rounded-full bg-muted-foreground/60 [animation-delay:150ms]" />
      <span className="size-1.5 animate-pulse rounded-full bg-muted-foreground/60 [animation-delay:300ms]" />
    </div>
  </div>
);

function MapGL({ children, styles, ...props }: MapProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreGL.Map | null>(null);
  const [isMounted, setIsMounted] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isStyleLoaded, setIsStyleLoaded] = useState(false);
  const { resolvedTheme } = useTheme();

  const mapStyles = useMemo(
    () => ({
      dark: styles?.dark ?? defaultStyles.dark,
      light: styles?.light ?? defaultStyles.light,
    }),
    [styles]
  );

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (!isMounted || !containerRef.current) return;

    const mapStyle = resolvedTheme === 'dark' ? mapStyles.dark : mapStyles.light;

    const mapInstance = new MapLibreGL.Map({
      container: containerRef.current,
      style: mapStyle,
      renderWorldCopies: false,
      attributionControl: {
        compact: true,
      },
      ...props,
    });

    const styleDataHandler = () => setIsStyleLoaded(true);
    const loadHandler = () => setIsLoaded(true);

    mapInstance.on('load', loadHandler);
    mapInstance.on('styledata', styleDataHandler);
    mapRef.current = mapInstance;

    return () => {
      mapInstance.off('load', loadHandler);
      mapInstance.off('styledata', styleDataHandler);
      mapInstance.remove();
      mapRef.current = null;
    };
  }, [isMounted]);

  useEffect(() => {
    if (mapRef.current) {
      setIsStyleLoaded(false);
      mapRef.current.setStyle(resolvedTheme === 'dark' ? mapStyles.dark : mapStyles.light, {
        diff: true,
      });
    }
  }, [resolvedTheme, mapStyles]);

  const isLoading = !isMounted || !isLoaded || !isStyleLoaded;

  return (
    <MapContext.Provider
      value={{
        map: mapRef.current,
        isLoaded: isMounted && isLoaded && isStyleLoaded,
      }}
    >
      <div ref={containerRef} className="relative h-full w-full">
        {isLoading && <DefaultLoader />}
        {/* guard against hydration error */}
        {isMounted && children}
      </div>
    </MapContext.Provider>
  );
}

type MarkerContextValue = {
  markerRef: React.RefObject<MapLibreGL.Marker | null>;
  markerElementRef: React.RefObject<HTMLDivElement | null>;
  map: MapLibreGL.Map | null;
  isReady: boolean;
};

const MarkerContext = createContext<MarkerContextValue | null>(null);

function useMarkerContext() {
  const context = useContext(MarkerContext);
  if (!context) {
    throw new Error('Marker components must be used within MapMarker');
  }
  return context;
}

type MapMarkerProps = {
  longitude: number;
  latitude: number;
  children: ReactNode;
  onClick?: (e: MouseEvent) => void;
  onMouseEnter?: (e: MouseEvent) => void;
  onMouseLeave?: (e: MouseEvent) => void;
  onDragStart?: (lngLat: { lng: number; lat: number }) => void;
  onDrag?: (lngLat: { lng: number; lat: number }) => void;
  onDragEnd?: (lngLat: { lng: number; lat: number }) => void;
} & Omit<MarkerOptions, 'element'>;

function MapMarker({
  longitude,
  latitude,
  children,
  onClick,
  onMouseEnter,
  onMouseLeave,
  onDragStart,
  onDrag,
  onDragEnd,
  draggable = false,
  ...markerOptions
}: MapMarkerProps) {
  const { map, isLoaded } = useMap();
  const markerRef = useRef<MapLibreGL.Marker | null>(null);
  const markerElementRef = useRef<HTMLDivElement | null>(null);
  const [isReady, setIsReady] = useState(false);
  const markerOptionsRef = useRef(markerOptions);

  useEffect(() => {
    if (!isLoaded || !map) return;

    const container = document.createElement('div');
    markerElementRef.current = container;

    const marker = new MapLibreGL.Marker({
      ...markerOptions,
      element: container,
      draggable,
    })
      .setLngLat([longitude, latitude])
      .addTo(map);

    markerRef.current = marker;

    const handleClick = (e: MouseEvent) => onClick?.(e);
    const handleMouseEnter = (e: MouseEvent) => onMouseEnter?.(e);
    const handleMouseLeave = (e: MouseEvent) => onMouseLeave?.(e);

    container.addEventListener('click', handleClick);
    container.addEventListener('mouseenter', handleMouseEnter);
    container.addEventListener('mouseleave', handleMouseLeave);

    const handleDragStart = () => {
      const lngLat = marker.getLngLat();
      onDragStart?.({ lng: lngLat.lng, lat: lngLat.lat });
    };
    const handleDrag = () => {
      const lngLat = marker.getLngLat();
      onDrag?.({ lng: lngLat.lng, lat: lngLat.lat });
    };
    const handleDragEnd = () => {
      const lngLat = marker.getLngLat();
      onDragEnd?.({ lng: lngLat.lng, lat: lngLat.lat });
    };

    marker.on('dragstart', handleDragStart);
    marker.on('drag', handleDrag);
    marker.on('dragend', handleDragEnd);

    setIsReady(true);

    return () => {
      container.removeEventListener('click', handleClick);
      container.removeEventListener('mouseenter', handleMouseEnter);
      container.removeEventListener('mouseleave', handleMouseLeave);

      marker.off('dragstart', handleDragStart);
      marker.off('drag', handleDrag);
      marker.off('dragend', handleDragEnd);

      marker.remove();
      markerRef.current = null;
      markerElementRef.current = null;
      setIsReady(false);
    };
  }, [map, isLoaded]);

  useEffect(() => {
    markerRef.current?.setLngLat([longitude, latitude]);
  }, [longitude, latitude]);

  useEffect(() => {
    markerRef.current?.setDraggable(draggable);
  }, [draggable]);

  useEffect(() => {
    if (!markerRef.current) return;
    const prev = markerOptionsRef.current;

    if (prev.offset !== markerOptions.offset) {
      markerRef.current.setOffset(markerOptions.offset ?? [0, 0]);
    }
    if (prev.rotation !== markerOptions.rotation) {
      markerRef.current.setRotation(markerOptions.rotation ?? 0);
    }
    if (prev.rotationAlignment !== markerOptions.rotationAlignment) {
      markerRef.current.setRotationAlignment(markerOptions.rotationAlignment ?? 'auto');
    }
    if (prev.pitchAlignment !== markerOptions.pitchAlignment) {
      markerRef.current.setPitchAlignment(markerOptions.pitchAlignment ?? 'auto');
    }

    markerOptionsRef.current = markerOptions;
  }, [markerOptions]);

  return (
    <MarkerContext.Provider value={{ markerRef, markerElementRef, map, isReady }}>
      {children}
    </MarkerContext.Provider>
  );
}

type MarkerContentProps = {
  children?: ReactNode;
  className?: string;
};

function MarkerContent({ children, className }: MarkerContentProps) {
  const { markerElementRef, isReady } = useMarkerContext();

  if (!isReady || !markerElementRef.current) return null;

  return createPortal(
    <div className={cn('relative cursor-pointer', className)}>
      {children || <DefaultMarkerIcon />}
    </div>,
    markerElementRef.current
  );
}

function DefaultMarkerIcon() {
  return (
    <div className="relative h-4 w-4 rounded-full border-2 border-white bg-blue-500 shadow-lg" />
  );
}

type MarkerPopupProps = {
  children: ReactNode;
  className?: string;
  closeButton?: boolean;
} & Omit<PopupOptions, 'className'>;

function MarkerPopup({
  children,
  className,
  closeButton = false,
  ...popupOptions
}: MarkerPopupProps) {
  const { markerRef, isReady } = useMarkerContext();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const popupRef = useRef<MapLibreGL.Popup | null>(null);
  const [mounted, setMounted] = useState(false);
  const popupOptionsRef = useRef(popupOptions);

  useEffect(() => {
    if (!isReady || !markerRef.current) return;

    const container = document.createElement('div');
    containerRef.current = container;

    const popup = new MapLibreGL.Popup({
      offset: 16,
      ...popupOptions,
      closeButton: false,
    })
      .setMaxWidth('none')
      .setDOMContent(container);

    popupRef.current = popup;
    markerRef.current.setPopup(popup);
    setMounted(true);

    return () => {
      popup.remove();
      popupRef.current = null;
      containerRef.current = null;
      setMounted(false);
    };
  }, [isReady]);

  useEffect(() => {
    if (!popupRef.current) return;
    const prev = popupOptionsRef.current;

    if (prev.offset !== popupOptions.offset) {
      popupRef.current.setOffset(popupOptions.offset ?? 16);
    }
    if (prev.maxWidth !== popupOptions.maxWidth && popupOptions.maxWidth) {
      popupRef.current.setMaxWidth(popupOptions.maxWidth ?? 'none');
    }

    popupOptionsRef.current = popupOptions;
  }, [popupOptions]);

  const handleClose = () => popupRef.current?.remove();

  if (!mounted || !containerRef.current) return null;

  return createPortal(
    <div
      className={cn(
        'fade-in-0 zoom-in-95 relative animate-in rounded-md border bg-popover p-3 text-popover-foreground shadow-md',
        className
      )}
    >
      {closeButton && (
        <button
          type="button"
          onClick={handleClose}
          className="absolute top-1 right-1 z-10 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
          aria-label="Close popup"
        >
          <X className="h-4 w-4" />
          <span className="sr-only">Close</span>
        </button>
      )}
      {children}
    </div>,
    containerRef.current
  );
}

type MarkerTooltipProps = {
  children: ReactNode;
  className?: string;
} & Omit<PopupOptions, 'className' | 'closeButton' | 'closeOnClick'>;

function MarkerTooltip({ children, className, ...popupOptions }: MarkerTooltipProps) {
  const { markerRef, markerElementRef, map, isReady } = useMarkerContext();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const popupRef = useRef<MapLibreGL.Popup | null>(null);
  const [mounted, setMounted] = useState(false);
  const popupOptionsRef = useRef(popupOptions);

  useEffect(() => {
    if (!isReady || !markerRef.current || !markerElementRef.current || !map) return;

    const container = document.createElement('div');
    containerRef.current = container;

    const popup = new MapLibreGL.Popup({
      offset: 16,
      ...popupOptions,
      closeOnClick: true,
      closeButton: false,
    })
      .setMaxWidth('none')
      .setDOMContent(container);

    popupRef.current = popup;

    const markerElement = markerElementRef.current;
    const marker = markerRef.current;

    const handleMouseEnter = () => {
      popup.setLngLat(marker.getLngLat()).addTo(map);
    };
    const handleMouseLeave = () => popup.remove();

    markerElement.addEventListener('mouseenter', handleMouseEnter);
    markerElement.addEventListener('mouseleave', handleMouseLeave);
    setMounted(true);

    return () => {
      markerElement.removeEventListener('mouseenter', handleMouseEnter);
      markerElement.removeEventListener('mouseleave', handleMouseLeave);
      popup.remove();
      popupRef.current = null;
      containerRef.current = null;
      setMounted(false);
    };
  }, [isReady, map]);

  useEffect(() => {
    if (!popupRef.current) return;
    const prev = popupOptionsRef.current;

    if (prev.offset !== popupOptions.offset) {
      popupRef.current.setOffset(popupOptions.offset ?? 16);
    }
    if (prev.maxWidth !== popupOptions.maxWidth && popupOptions.maxWidth) {
      popupRef.current.setMaxWidth(popupOptions.maxWidth ?? 'none');
    }

    popupOptionsRef.current = popupOptions;
  }, [popupOptions]);

  if (!mounted || !containerRef.current) return null;

  return createPortal(
    <div
      className={cn(
        'fade-in-0 zoom-in-95 animate-in rounded-md bg-foreground px-2 py-1 text-background text-xs shadow-md',
        className
      )}
    >
      {children}
    </div>,
    containerRef.current
  );
}

